function validate(input) {
  const [str, times] = input;
  if (typeof str !== 'string' || str.length < 1 || str.length > 1000) return 'str must be a string of 1 to 1000 characters.';
  if (!Number.isInteger(times) || times < 1 || times > 1000) return 'times must be an integer from 1 to 1000.';
  return null;
}

