function adapt(input, solve, kit) {
  const [str, times] = input;
  if (typeof str.replicate !== 'function') throw new Error('Strings have no replicate method yet: assign a function to String.prototype.replicate.');
  // The exercise asks for a solution without the built-in repeat.
  const builtin = String.prototype.repeat;
  String.prototype.repeat = function () { throw new Error('Solve this without the built-in String.prototype.repeat.'); };
  let result;
  try { result = str.replicate(times); } finally { String.prototype.repeat = builtin; }
  // In sloppy mode this is a String object; accept one holding the right text.
  if (result instanceof String) result = result.valueOf();
  if (typeof result !== 'string') throw new Error('replicate must return a string.');
  kit.trace(`${JSON.stringify(str.length > 20 ? `${str.slice(0, 20)}...` : str)}.replicate(${times}) returns ${result.length} characters`);
  return result;
}

