  const word = (length, alphabet) => Array.from({ length }, () => alphabet[Math.floor(rand() * alphabet.length)]).join('');
  if (size === 'small') return [word(1 + Math.floor(rand() * 4), 'ab c'), 1 + Math.floor(rand() * 9)];
  if (rand() < 0.5) return [word(500 + Math.floor(rand() * 501), 'abcdefghijklmnopqrstuvwxyz'), 1 + Math.floor(rand() * 20)];
  return [word(1 + Math.floor(rand() * 10), 'abcxyz'), 500 + Math.floor(rand() * 501)];
}
